content.text:
The evidence points to two faults. The first is a consign-service pod restart at the start of the window that reached users as 503s on ui-dashboard's consign path. The second is a slowdown inside ts-food-service's own methods that reached users through preserve and ui-dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-consign-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_container_name AS container, metric, min(value) AS min_v, max(value) AS max_v, count(*) AS n FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_container_name='ts-consign-service' GROUP BY 1,2",
          "claim": "Consign container restart counter reads 1 for the whole abnormal window, while normal shows 0, so it restarted at the window start."
        },
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS t, sum(CASE WHEN service_name='ts-consign-service' AND attr_span_kind='Server' THEN 1 ELSE 0 END) AS consign_server_spans, sum(CASE WHEN service_name='ts-ui-dashboard' AND span_name LIKE '%consignservice%' AND attr_http_response_status_code=503 THEN 1 ELSE 0 END) AS ui_consign_503 FROM abnormal_traces GROUP BY 1 ORDER BY 1",
          "claim": "Consign emits no server spans in the first minute, and ui-dashboard consign requests return 503 only in the first two minutes."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, span_name, count(*) AS n, round(avg(CASE WHEN has_child THEN 1.0 ELSE 0 END),2) AS share_with_consign_child, round(quantile_cont(ms,0.5),1) AS p50_ms FROM (SELECT 'abn' AS p, u.span_name, u.duration/1e6 AS ms, EXISTS (SELECT 1 FROM abnormal_traces c WHERE c.parent_span_id=u.span_id AND c.service_name='ts-consign-service') AS has_child FROM abnormal_traces u WHERE u.service_name='ts-ui-dashboard' AND u.attr_http_response_status_code=503 AND u.span_name LIKE '%consignservice%') GROUP BY 1,2",
          "claim": "The 503 ui-dashboard consign requests never reach consign-service: no child consign span exists for them."
        }
      ]
    },
    {
      "service": "ts-food-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT CASE WHEN trace_id IS NOT NULL THEN 'abn' END AS p, span_name, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='ts-food-service' AND span_name IN ('FoodOrderRepository.save','FoodController.getAllFood','FoodController.createFoodOrder') GROUP BY 1,2 ORDER BY 2",
          "claim": "Food methods getAllFood and FoodOrderRepository.save have much higher p95 in the abnormal window, e.g. save p95 about 779 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM normal_traces WHERE service_name='ts-food-service' AND span_name IN ('FoodOrderRepository.save','FoodController.getAllFood','FoodController.createFoodOrder') GROUP BY 1 ORDER BY 1",
          "claim": "Same food methods in the normal period: save p95 about 5 ms and getAllFood p95 about 61 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, round(quantile_cont(duration,0.5)/1e6,1) AS db_p50_ms, round(quantile_cont(duration,0.95)/1e6,1) AS db_p95_ms FROM abnormal_traces WHERE service_name='ts-food-service' AND span_name IN ('INSERT ts.food_order','SELECT ts.food_order') GROUP BY 1",
          "claim": "Food's database spans stay fast in the abnormal window (p95 about 2 ms), so the slow time is inside the application method."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-consign-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT date_trunc('minute', time) AS t, count(*) AS ui_consign_requests, sum(CASE WHEN attr_http_response_status_code=503 THEN 1 ELSE 0 END) AS failed_503 FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%consignservice%' GROUP BY 1 ORDER BY 1",
          "claim": "ui-dashboard consign/account requests fail with 503 in the same minutes that consign-service is down."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, count(*) AS n, round(quantile_cont(sd,0.5)/1e6,1) AS food_server_p50_ms, round(quantile_cont(sd,0.95)/1e6,1) AS food_server_p95_ms FROM (SELECT 'abn' AS p, s.duration sd FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND s.service_name='ts-food-service' AND c.attr_span_kind='Client' UNION ALL SELECT 'nrm', s.duration FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-preserve-service' AND s.service_name='ts-food-service' AND c.attr_span_kind='Client') GROUP BY 1",
          "claim": "Preserve's calls into food-service have server p95 about 812 ms in the abnormal window versus about 17 ms normally."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, span_name, count(*) AS n, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'nrm', * FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY 1,2 ORDER BY 2,1",
          "claim": "ui-dashboard's preserve/order POST requests slow from roughly 0.8 s to 1 s at p95 when preserve waits on food."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms, round(quantile_cont(duration,0.95)/1e6,1) AS p95_ms FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'nrm', * FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%foodservice%' GROUP BY 1",
          "claim": "ui-dashboard food-service requests are slower at p95 in the abnormal window, from about 46 ms to about 207 ms."
        }
      ]
    }
  ]
}
```

